#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Values captured by this wizard are remembered in .deploy.env (git-ignored).
ENV_FILE=".deploy.env"
PROJECT="SymmetryPrototype.xcodeproj"
SCHEME="SymmetryPrototype"
XCCONFIG="Config/Local.xcconfig"
DERIVED="build/DerivedData"

# detect_teams prints "TEAMID<tab>name<tab>kind<tab>apple-id" for every team Xcode knows
# from the Apple IDs signed in under Xcode > Settings > Accounts.
detect_teams() {
  defaults export com.apple.dt.Xcode - 2>/dev/null | python3 -c '
import plistlib, sys
try:
    d = plistlib.loads(sys.stdin.buffer.read())
except Exception:
    sys.exit(0)
seen = set()
for acct, lst in (d.get("IDEProvisioningTeams") or {}).items():
    for t in lst or []:
        tid = t.get("teamID")
        if not tid or tid in seen:
            continue
        seen.add(tid)
        kind = "personal team" if t.get("isFreeProvisioningTeam") else (t.get("teamType") or "team")
        name = t.get("teamName") or ""
        print(tid + "\t" + name + "\t" + kind + "\t" + str(acct))
' 2>/dev/null || true
}

# ask_team_id VAR: a Team ID is exactly 10 letters or digits. Offers the teams Xcode
# knows; Enter takes the first one. Re-asks until the value is valid.
ask_team_id() {
  local key="$1" value default="" teams
  teams=$(detect_teams)
  if [[ -n "$teams" ]]; then
    say "Teams found in Xcode's accounts:"
    while IFS=$'\t' read -r tid name kind acct; do
      note "  $tid  $name ($kind, $acct)"
      [[ -z "$default" ]] && default="$tid"
    done <<< "$teams"
  else
    warn "Xcode has no signed-in team yet. Open Xcode > Settings > Accounts, add your Apple ID, then come back."
    note "A free Apple ID gives you a personal team that can install on your own iPhone."
  fi
  while true; do
    if [[ -n "$default" ]]; then
      ask "$key" "Team ID [Enter for $default]:" || true
    else
      ask "$key" "Paste the Team ID (10 letters or digits):" || true
    fi
    value="${!key}"
    value="${value//[[:space:]]/}"
    [[ -z "$value" && -n "$default" ]] && value="$default"
    if [[ "$value" =~ ^[A-Z0-9]{10}$ ]]; then printf -v "$key" '%s' "$value"; return; fi
    warn "'$value' is not a Team ID. It looks like A1B2C3D4E5: developer.apple.com/account > Membership details, or sign in under Xcode > Settings > Accounts and re-run."
    if [[ -z "$teams" ]]; then
      pause "Press Enter after adding the account in Xcode to look for teams again."
      teams=$(detect_teams); default=""
      [[ -n "$teams" ]] && default=$(printf '%s\n' "$teams" | head -n1 | cut -f1)
    fi
  done
}

# ask_bundle_id VAR: reverse-DNS, e.g. org.example.App. Empty keeps the default.
ask_bundle_id() {
  local key="$1" value default="org.research.symmetry.SymmetryPrototype"
  while true; do
    ask "$key" "Bundle identifier [$default]:" || true
    value="${!key}"
    value="${value//[[:space:]]/}"
    [[ -z "$value" ]] && value="$default"
    if [[ "$value" =~ ^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$ ]]; then printf -v "$key" '%s' "$value"; return; fi
    warn "'$value' is not a bundle identifier. Use dot-separated words like $default."
  done
}

# write_xcconfig TEAM BUNDLE writes the git-ignored signing config Xcode reads.
write_xcconfig() {
  mkdir -p Config
  printf 'DEVELOPMENT_TEAM = %s\nPRODUCT_BUNDLE_IDENTIFIER = %s\n' "$1" "$2" > "$XCCONFIG"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$XCCONFIG"
}

run_wizard() {

cd "$(dirname "$0")/.."
TOTAL_STAGES=7

banner "Deploy the Symmetry prototype to your iPhone"

# ── 1. Xcode ──────────────────────────────────────────────────────────────
stage "Xcode 16 or later"
say "The app builds only with Xcode on a Mac. Checking what is installed."
if [[ "$(uname -s)" != "Darwin" ]]; then
  warn "This is not macOS. Run this wizard on a Mac."
  exit 1
fi
# Loop until xcodebuild works: Xcode installed AND selected as the developer directory.
while ! xcodebuild -version >/dev/null 2>&1; do
  XCODE_APP=""
  for candidate in /Applications/Xcode.app /Applications/Xcode-*.app; do
    [[ -d "$candidate" ]] && { XCODE_APP="$candidate"; break; }
  done
  if [[ -n "$XCODE_APP" ]]; then
    say "Found $XCODE_APP, but the active developer directory is:"
    note "  $(xcode-select -p 2>/dev/null || echo unknown)"
    if confirm "Point xcode-select at $XCODE_APP now? (asks for your Mac password)"; then
      sudo xcode-select -s "$XCODE_APP/Contents/Developer"
      say "Accepting the Xcode license and finishing first-launch setup."
      sudo xcodebuild -license accept || true
      sudo xcodebuild -runFirstLaunch || true
    else
      pause "Run it yourself, then press Enter to check again."
    fi
  else
    warn "Xcode is not installed (only the Command Line Tools are)."
    open_url "https://apps.apple.com/app/xcode/id497799835"
    step "Install Xcode from the App Store. It is a large download; wait until it finishes."
    step "Open Xcode once and accept the license, then come back here."
    pause "Press Enter when Xcode is installed."
  fi
done
xcodebuild -version | head -n1
XCODE_MAJOR=$(xcodebuild -version | head -n1 | awk '{print $2}' | cut -d. -f1)
if [[ "${XCODE_MAJOR:-0}" -lt 16 ]]; then
  warn "Xcode 16 or later is required (found major version ${XCODE_MAJOR:-unknown})."
  pause "Update Xcode from the App Store, then press Enter."
fi
step "In Xcode, open Settings > Accounts and sign in with the Apple ID of your developer team."
note "Automatic signing needs that account in Xcode, even when building from the terminal."
pause "Press Enter once the account is added."

# ── 2. XcodeGen ───────────────────────────────────────────────────────────
stage "XcodeGen"
say "The Xcode project is generated from project.yml so it never goes stale."
if ! command -v xcodegen >/dev/null 2>&1; then
  if ! command -v brew >/dev/null 2>&1; then
    open_url "https://brew.sh"
    step "Install Homebrew with the command shown on that page."
    pause "Press Enter when brew is installed."
  fi
  say "Installing XcodeGen with Homebrew."
  brew install xcodegen
fi
xcodegen --version

# ── 3. Team and bundle identifier ─────────────────────────────────────────
stage "Apple Developer team"
say "Device builds must be signed by your team."
if saved=$(_existing DEVELOPMENT_TEAM) && ! [[ "${saved//[[:space:]]/}" =~ ^[A-Z0-9]{10}$ ]]; then
  warn "The remembered Team ID '$saved' is not valid; it will be asked again."
  write_env DEVELOPMENT_TEAM ""
fi
if saved=$(_existing PRODUCT_BUNDLE_IDENTIFIER) && ! [[ "${saved//[[:space:]]/}" =~ ^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$ ]]; then
  warn "The remembered bundle identifier '$saved' is not valid; it will be asked again."
  write_env PRODUCT_BUNDLE_IDENTIFIER ""
fi
open_url "https://developer.apple.com/account"
step "Sign in, open Membership details, and copy the Team ID (10 characters)."
ask_team_id DEVELOPMENT_TEAM
step "Choose the bundle identifier. It must be unique to your team; the default is fine for a personal or research team."
ask_bundle_id PRODUCT_BUNDLE_IDENTIFIER
write_env DEVELOPMENT_TEAM "$DEVELOPMENT_TEAM"
write_env PRODUCT_BUNDLE_IDENTIFIER "$PRODUCT_BUNDLE_IDENTIFIER"
write_xcconfig "$DEVELOPMENT_TEAM" "$PRODUCT_BUNDLE_IDENTIFIER"

# ── 4. Generate the project ───────────────────────────────────────────────
stage "Generate the Xcode project"
xcodegen generate
say "Generated $PROJECT."

# ── 5. Connect the iPhone ─────────────────────────────────────────────────
stage "Connect your iPhone"
step "Plug the iPhone into this Mac with a cable and unlock it."
step "If the phone asks 'Trust This Computer?', tap Trust."
step "On the phone, turn on Settings > Privacy & Security > Developer Mode, then restart it if asked."
pause "Press Enter when the phone is connected and unlocked."
say "Connected devices:"
xcrun devicectl list devices 2>/dev/null || xcrun xctrace list devices
step "Copy the Identifier column value for your iPhone (not a simulator)."
ask DEVICE_ID "Paste the device identifier:"
write_env DEVICE_ID "$DEVICE_ID"

# ── 6. Build, install, launch ─────────────────────────────────────────────
stage "Build, install and launch"
say "Building a Debug build signed with automatic provisioning. The first build registers the device and creates a profile."
mkdir -p build
APP_PATH="$DERIVED/Build/Products/Debug-iphoneos/$SCHEME.app"
while true; do
  rm -rf "$APP_PATH"
  xcodebuild build \
    -project "$PROJECT" -scheme "$SCHEME" -configuration Debug \
    -destination "id=$DEVICE_ID" \
    -derivedDataPath "$DERIVED" \
    -allowProvisioningUpdates -allowProvisioningDeviceRegistration \
    > build/device-build.log 2>&1 || true
  grep -E "error:|warning: .*signing|BUILD (SUCCEEDED|FAILED)" build/device-build.log | sort -u | head -n 30 || true
  [[ -d "$APP_PATH" ]] && break
  printf '\n'
  if grep -q "Developer Mode disabled" build/device-build.log; then
    warn "The iPhone has Developer Mode turned off."
    step "On the phone: Settings > Privacy & Security > Developer Mode (at the bottom) > turn on."
    step "Tap Restart. After it reboots and you unlock it, confirm 'Turn on Developer Mode'."
    step "Keep the phone unlocked and connected."
    pause "Press Enter to build again."
  elif grep -qiE "not paired|pairing|locked|Trust This Computer|device is busy|not available|Timed out waiting" build/device-build.log; then
    warn "The Mac cannot talk to the phone yet."
    step "Unlock the phone, tap Trust if it asks, and wait until it finishes connecting (unplug and replug if needed)."
    pause "Press Enter to build again."
  elif grep -qiE "No profiles|signing|provisioning|No Account|Team" build/device-build.log; then
    warn "Signing failed. Common causes: the Apple ID is not added in Xcode > Settings > Accounts, the Team ID is wrong, or the bundle ID is taken by another team."
    step "Fix the account or Team ID, then press Enter. Current team: $DEVELOPMENT_TEAM, bundle ID: $PRODUCT_BUNDLE_IDENTIFIER"
    if confirm "Re-enter the Team ID and bundle ID?"; then
      ask_team_id DEVELOPMENT_TEAM
      ask_bundle_id PRODUCT_BUNDLE_IDENTIFIER
      write_env DEVELOPMENT_TEAM "$DEVELOPMENT_TEAM"
      write_env PRODUCT_BUNDLE_IDENTIFIER "$PRODUCT_BUNDLE_IDENTIFIER"
      write_xcconfig "$DEVELOPMENT_TEAM" "$PRODUCT_BUNDLE_IDENTIFIER"
      xcodegen generate
    fi
  else
    warn "The build failed for another reason. The full log is in build/device-build.log."
    if ! confirm "Try the build again?"; then
      say "Open $PROJECT in Xcode, select your iPhone as the run destination and press Run; Xcode shows the exact error."
      exit 1
    fi
  fi
done
say "Installing on the phone."
xcrun devicectl device install app --device "$DEVICE_ID" "$APP_PATH"
note "With a personal (free) team, the phone may now ask you to trust the developer: Settings > General > VPN & Device Management."
say "Launching."
xcrun devicectl device process launch --device "$DEVICE_ID" "$PRODUCT_BUNDLE_IDENTIFIER" || warn "Launch failed; open the app from the home screen."
step "On the phone: accept the research notice, allow camera access, and work through the acceptance checklist in README.md."

# ── 7. Optional: TestFlight from GitHub Actions ───────────────────────────
stage "Optional: TestFlight uploads from GitHub Actions"
say "The TestFlight workflow needs an App Store Connect API key and an app record."
if confirm "Set up TestFlight secrets now?"; then
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Identifiers > + > App IDs > App. Register $PRODUCT_BUNDLE_IDENTIFIER with the Camera capability left unticked (it needs no capability)."
  pause "Press Enter when the identifier exists."
  open_url "https://appstoreconnect.apple.com/apps"
  step "Apps > + > New App. Pick the bundle ID you just registered, name it, and create the record."
  pause "Press Enter when the app record exists."
  open_url "https://appstoreconnect.apple.com/access/integrations/api"
  step "Users and Access > Integrations > App Store Connect API > Team Keys > Generate API Key."
  step "Give it the Admin role (cloud-managed signing needs it). Copy the Issuer ID and the Key ID, and download the .p8 file once."
  ask APP_STORE_CONNECT_ISSUER_ID "Paste the Issuer ID:"
  ask APP_STORE_CONNECT_KEY_ID "Paste the Key ID:"
  ask P8_PATH "Path to the downloaded AuthKey_*.p8 file:"
  if [[ -f "$P8_PATH" ]]; then
    P8_B64=$(base64 < "$P8_PATH" | tr -d '\n')
    write_env APP_STORE_CONNECT_ISSUER_ID "$APP_STORE_CONNECT_ISSUER_ID"
    write_env APP_STORE_CONNECT_KEY_ID "$APP_STORE_CONNECT_KEY_ID"
    set_secret APP_STORE_CONNECT_ISSUER_ID "$APP_STORE_CONNECT_ISSUER_ID"
    set_secret APP_STORE_CONNECT_KEY_ID "$APP_STORE_CONNECT_KEY_ID"
    set_secret APP_STORE_CONNECT_API_KEY_P8 "$P8_B64"
    set_var APPLE_TEAM_ID "$DEVELOPMENT_TEAM"
    set_var APP_BUNDLE_ID "$PRODUCT_BUNDLE_IDENTIFIER"
    note "Run the TestFlight workflow from the Actions tab (workflow_dispatch) to upload a build."
  else
    warn "No file at $P8_PATH; skipping TestFlight secrets. Re-run this wizard to set them later."
  fi
else
  note "Skipped. Re-run this wizard any time to set up TestFlight."
fi

finish
}

run_wizard "$@"; exit
